// Maintained regression cases copied from rolldown-plugin-dts.
use support::Case;

macro_rules! cases {
    ($($name:ident: { $($fields:tt)* }),* $(,)?) => {
        const CASES: &[Case] = &[$(Case { $($fields)* ..Case::DEFAULT }),*];
        #[test]
        fn rolldown_inventory_is_complete() { support::inventory(CASES); }
        $(#[test] fn $name() { support::run(&Case { $($fields)* ..Case::DEFAULT }); })*
    };
}

